SourceCode.Declaration:
/******************************************************************************* * BULK SALES ORDER GENERATION JOB * * Purpose: Generates / processes sales orders in parallel using batch tasks. * All logic lives in this single class — no additional class files needed. * * ── Processing modes ────────────────────────────────────────────────────────── * * Copy mode Copy an existing template order N times. * Each task creates a brand-new order from the source and runs * the enabled parts on it. * Fields: Source Order ID + Number of copies * * List mode Process a set of already-existing orders. * Comma-separated order IDs. Each task runs the enabled parts on * one order from the list (Part 1 is a no-op / skipped in this mode * because the orders already exist). * Fields: Order IDs (comma-separated) * * ── Part enable / disable ───────────────────────────────────────────────────── * * Five checkboxes, one per part. Parts gate each other sequentially: * Part 2 is only enabled when Part 1 is checked. * Part 3 is only enabled when Part 2 is checked. * Part 4 is only enabled when Part 3 is checked. * Part 5 is only enabled when Part 4 is checked. * Unchecking a part automatically unchecks and disables all later parts. * * Part 1 – Sales Order Creation (copy mode only — skipped in list mode) * Part 2 – Confirmation (TMS engine + SalesFormLetter) * Part 3 – Extraction (picking list, guide check, shipment load) * Part 4 – Dallas Picking List Completion * Part 5a – Totes (create totes, update CCR on load lines) * Part 5b – Container (create container record) * Part 5c – Shipment Confirmation (confirm shipment, update status to Loaded) * * ── Threading model ─────────────────────────────────────────────────────────── * * orderIndex == 0 → dispatcher: submits a BatchHeader with one task per order * orderIndex > 0 → worker: processes the single order assigned to this task * * The batch framework runs all tasks in parallel up to the server's slot limit. * *******************************************************************************/ class METTESTBulkSalesOrderGenerationJob extends RunBaseBatch { // ========================================================================= // CLASS VARIABLES // =========================================================================
// Mode NoYes isCopyMode; // Yes = copy source order N times; No = process list
// Copy-mode parameters str sourceOrderId; // template order to copy from int orderCount; // number of copies to create
// List-mode parameter str orderIdList; // comma-separated order IDs to process
// Part enable/disable flags NoYes runPart1; // Part 1: Sales Order Creation NoYes runPart2; // Part 2: Confirmation NoYes runPart3; // Part 3: Extraction NoYes runPart4; // Part 4: Dallas Picking List NoYes runPart5a; // Part 5a: Totes NoYes runPart5b; // Part 5b: Container NoYes runPart5c; // Part 5c: Shipment Confirmation
// Batch task identity (set by dispatcher; not shown in dialog) int orderIndex; // 0 = dispatcher, 1..N = worker task number str taskOrderId; // order ID assigned to this task
// Dialog fields DialogField dfIsCopyMode; DialogField dfSourceOrderId; DialogField dfOrderCount; DialogField dfOrderIdList; DialogField dfRunPart1; DialogField dfRunPart2; DialogField dfRunPart3; DialogField dfRunPart4; DialogField dfRunPart5a; DialogField dfRunPart5b; DialogField dfRunPart5c;
#define.CurrentVersion(1) #localmacro.CurrentList isCopyMode, sourceOrderId, orderCount, orderIdList, runPart1, runPart2, runPart3, runPart4, runPart5a, runPart5b, runPart5c, orderIndex, taskOrderId #endmacro
// ========================================================================= // INITIALISATION // =========================================================================
}

Method.Source:
public void new()
{
    super();
    // Defaults: copy mode, all parts on
    isCopyMode    = NoYes::Yes;
    sourceOrderId = '700000719';
    orderCount    = 1;
    runPart1      = NoYes::Yes;
    runPart2      = NoYes::Yes;
    runPart3      = NoYes::Yes;
    runPart4      = NoYes::Yes;
    runPart5a     = NoYes::Yes;
    runPart5b     = NoYes::Yes;
    runPart5c     = NoYes::Yes;
}

// =========================================================================
// RUNBASEBATCH OVERRIDES
// =========================================================================

static ClassDescription description()
{
    return strFmt("Bulk Sales Order Generation for testing: %1", METBatchLogOperation::SalesFinalizationAutomation);
}

public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

public boolean unpack(container _packedClass)
{
    switch (RunBase::getVersion(_packedClass))
    {
        case #CurrentVersion:
            // Position 1 = version (skipped). Positions match the order in #CurrentList.
            isCopyMode    = conPeek(_packedClass, 2);
            sourceOrderId = conPeek(_packedClass, 3);
            orderCount    = conPeek(_packedClass, 4);
            orderIdList   = conPeek(_packedClass, 5);
            runPart1      = conPeek(_packedClass, 6);
            runPart2      = conPeek(_packedClass, 7);
            runPart3      = conPeek(_packedClass, 8);
            runPart4      = conPeek(_packedClass, 9);
            runPart5a     = conPeek(_packedClass, 10);
            runPart5b     = conPeek(_packedClass, 11);
            runPart5c     = conPeek(_packedClass, 12);
            orderIndex    = conPeek(_packedClass, 13);
            taskOrderId   = conPeek(_packedClass, 14);
            return true;
    }
    return false;
}

// =========================================================================
// DIALOG
// =========================================================================

public Object dialog()
{
    DialogRunbase   dlg = super();
    ;

    // ── Mode ──────────────────────────────────────────────────────────────
    dfIsCopyMode    = dlg.addField(identifierStr(NoYes),       "Copy mode (off = process existing order list)");
    dfSourceOrderId = dlg.addField(identifierStr(SalesIdBase), "Source Order ID  [copy mode]");
    dfOrderCount    = dlg.addField(identifierStr(Integer),     "Number of copies  [copy mode]");
    dfOrderIdList   = dlg.addField(identifierStr(Notes),       "Order IDs comma-separated  [list mode]");

    // ── Parts ─────────────────────────────────────────────────────────────
    dfRunPart1      = dlg.addField(identifierStr(NoYes),       "Part 1: Sales Order Creation");
    dfRunPart2      = dlg.addField(identifierStr(NoYes),       "Part 2: Confirmation (TMS + SalesFormLetter)");
    dfRunPart3      = dlg.addField(identifierStr(NoYes),       "Part 3: Extraction (picking list, shipment load)");
    dfRunPart4      = dlg.addField(identifierStr(NoYes),       "Part 4: Dallas Picking List Completion");
    dfRunPart5a     = dlg.addField(identifierStr(NoYes),       "Part 5a: Totes (create totes + update CCR on load lines)");
    dfRunPart5b     = dlg.addField(identifierStr(NoYes),       "Part 5b: Container (create container record)");
    dfRunPart5c     = dlg.addField(identifierStr(NoYes),       "Part 5c: Shipment Confirmation (confirm + update status to Loaded)");

    // ── Initial values ────────────────────────────────────────────────────
    dfIsCopyMode.value(   isCopyMode);
    dfSourceOrderId.value(sourceOrderId);
    dfOrderCount.value(   orderCount);
    dfOrderIdList.value(  orderIdList);
    dfRunPart1.value(     runPart1);
    dfRunPart2.value(     runPart2);
    dfRunPart3.value(     runPart3);
    dfRunPart4.value(     runPart4);
    dfRunPart5a.value(    runPart5a);
    dfRunPart5b.value(    runPart5b);
    dfRunPart5c.value(    runPart5c);

    return dlg;
}

public void dialogPostRun(DialogRunbase _dialog)
{
    super(_dialog);

    // Register interactive modification overrides
    dfIsCopyMode.registerOverrideMethod(methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, modeModified), this);
    dfRunPart1.registerOverrideMethod(  methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, part1Modified), this);
    dfRunPart2.registerOverrideMethod(  methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, part2Modified), this);
    dfRunPart3.registerOverrideMethod(  methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, part3Modified), this);
    dfRunPart4.registerOverrideMethod(  methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, part4Modified), this);
    dfRunPart5a.registerOverrideMethod( methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, part5aModified), this);
    dfRunPart5b.registerOverrideMethod( methodStr(FormCheckBoxControl, modified),
                                         methodStr(METTESTBulkSalesOrderGenerationJob, part5bModified), this);

    // Apply initial enabled states (important when re-opening a saved dialog)
    this.applyDialogState();
}

// Applies enabled/disabled state of all dialog fields based on current values.
// Called once on open, and re-called whenever a relevant field changes.
private void applyDialogState()
{
    boolean copy = dfIsCopyMode.value() == NoYes::Yes;

    dfSourceOrderId.control().enabled(copy);
    dfOrderCount.control().enabled(copy);
    dfOrderIdList.control().enabled(!copy);

    // Part cascading: Part N requires Part N-1 to be checked
    boolean p1  = dfRunPart1.value()  == NoYes::Yes;
    boolean p2  = dfRunPart2.value()  == NoYes::Yes;
    boolean p3  = dfRunPart3.value()  == NoYes::Yes;
    boolean p4  = dfRunPart4.value()  == NoYes::Yes;
    boolean p5a = dfRunPart5a.value() == NoYes::Yes;
    boolean p5b = dfRunPart5b.value() == NoYes::Yes;
    ;
    dfRunPart2.control().enabled(p1);
    dfRunPart3.control().enabled(p1 && p2);
    dfRunPart4.control().enabled(p1 && p2 && p3);
    dfRunPart5a.control().enabled(p1 && p2 && p3 && p4);
    dfRunPart5b.control().enabled(p1 && p2 && p3 && p4 && p5a);
    dfRunPart5c.control().enabled(p1 && p2 && p3 && p4 && p5a && p5b);
}

// ── Interactive override methods ──────────────────────────────────────────

public boolean modeModified(FormCheckBoxControl _control)
{
    boolean result = _control.modified();
    this.applyDialogState();
    return result;
}

public boolean part1Modified(FormCheckBoxControl _control)
{
    boolean result  = _control.modified();
    boolean checked = _control.value() != 0;
    if (!checked)
    {
        dfRunPart2.value(NoYes::No);
        dfRunPart3.value(NoYes::No);
        dfRunPart4.value(NoYes::No);
        dfRunPart5a.value(NoYes::No);
        dfRunPart5b.value(NoYes::No);
        dfRunPart5c.value(NoYes::No);
    }
    this.applyDialogState();
    return result;
}

public boolean part2Modified(FormCheckBoxControl _control)
{
    boolean result  = _control.modified();
    boolean checked = _control.value() != 0;
    if (!checked)
    {
        dfRunPart3.value(NoYes::No);
        dfRunPart4.value(NoYes::No);
        dfRunPart5a.value(NoYes::No);
        dfRunPart5b.value(NoYes::No);
        dfRunPart5c.value(NoYes::No);
    }
    this.applyDialogState();
    return result;
}

public boolean part3Modified(FormCheckBoxControl _control)
{
    boolean result  = _control.modified();
    boolean checked = _control.value() != 0;
    if (!checked)
    {
        dfRunPart4.value(NoYes::No);
        dfRunPart5a.value(NoYes::No);
        dfRunPart5b.value(NoYes::No);
        dfRunPart5c.value(NoYes::No);
    }
    this.applyDialogState();
    return result;
}

public boolean part4Modified(FormCheckBoxControl _control)
{
    boolean result  = _control.modified();
    boolean checked = _control.value() != 0;
    if (!checked)
    {
        dfRunPart5a.value(NoYes::No);
        dfRunPart5b.value(NoYes::No);
        dfRunPart5c.value(NoYes::No);
    }
    this.applyDialogState();
    return result;
}

public boolean part5aModified(FormCheckBoxControl _control)
{
    boolean result  = _control.modified();
    boolean checked = _control.value() != 0;
    if (!checked)
    {
        dfRunPart5b.value(NoYes::No);
        dfRunPart5c.value(NoYes::No);
    }
    this.applyDialogState();
    return result;
}

public boolean part5bModified(FormCheckBoxControl _control)
{
    boolean result  = _control.modified();
    boolean checked = _control.value() != 0;
    if (!checked)
    {
        dfRunPart5c.value(NoYes::No);
    }
    this.applyDialogState();
    return result;
}

// ──────────────────────────────────────────────────────────────────────────

public boolean getFromDialog()
{
    isCopyMode    = dfIsCopyMode.value();
    sourceOrderId = dfSourceOrderId.value();
    orderCount    = dfOrderCount.value();
    orderIdList   = dfOrderIdList.value();
    runPart1      = dfRunPart1.value();
    runPart2      = dfRunPart2.value();
    runPart3      = dfRunPart3.value();
    runPart4      = dfRunPart4.value();
    runPart5a     = dfRunPart5a.value();
    runPart5b     = dfRunPart5b.value();
    runPart5c     = dfRunPart5c.value();
    return super();
}

public boolean validate(Object _calledFrom = null)
{
    boolean isOk = super(_calledFrom);
    ;
    if (isCopyMode == NoYes::Yes)
    {
        if (!sourceOrderId)
        {
            isOk = checkFailed("Source Order ID is required in copy mode.");
        }
        if (orderCount <= 0)
        {
            isOk = checkFailed("Number of copies must be greater than 0.");
        }
    }
    else
    {
        if (!orderIdList)
        {
            isOk = checkFailed("Order IDs are required in list mode.");
        }
    }

    if (runPart1 == NoYes::No && runPart2 == NoYes::No && runPart3 == NoYes::No && runPart4 == NoYes::No
        && runPart5a == NoYes::No && runPart5b == NoYes::No && runPart5c == NoYes::No)
    {
        isOk = checkFailed("At least one part must be enabled.");
    }

    return isOk;
}

// =========================================================================
// DISPATCHER — builds BatchHeader with one task per order
// =========================================================================

private void dispatchBatchTasks()
{
    BatchHeader                     batchHeader;
    METTESTBulkSalesOrderGenerationJob     worker;
    List                            parsedIds;
    ListEnumerator                  le;
    str                             remaining, token;
    int                             commaPos, taskNum, totalTasks;
    ;

    batchHeader = BatchHeader::construct();

    if (isCopyMode == NoYes::Yes)
    {
        // ── Copy mode: N identical tasks, all copying from sourceOrderId ──
        batchHeader.parmCaption(strFmt("Bulk Order Generation - %1 copies of %2", orderCount, sourceOrderId));

        for (taskNum = 1; taskNum <= orderCount; taskNum++)
        {
            worker              = new METTESTBulkSalesOrderGenerationJob();
            worker.isCopyMode   = isCopyMode;
            worker.sourceOrderId = sourceOrderId;
            worker.orderCount   = orderCount;
            worker.runPart1     = runPart1;
            worker.runPart2     = runPart2;
            worker.runPart3     = runPart3;
            worker.runPart4     = runPart4;
            worker.runPart5a    = runPart5a;
            worker.runPart5b    = runPart5b;
            worker.runPart5c    = runPart5c;
            worker.orderIndex   = taskNum;
            worker.taskOrderId  = sourceOrderId;
            batchHeader.addTask(worker);
        }

        info(strFmt("Batch job submitted: %1 copy task(s) from order %2.", orderCount, sourceOrderId));
    }
    else
    {
        // ── List mode: one task per order ID in the list ──────────────────
        parsedIds = new List(Types::String);
        remaining = orderIdList;

        while (remaining)
        {
            commaPos = strFind(remaining, ',', 1, strLen(remaining));
            if (commaPos > 0)
            {
                token     = strLTrim(strRTrim(substr(remaining, 1, commaPos - 1)));
                remaining = strLTrim(strRTrim(substr(remaining, commaPos + 1, strLen(remaining) - commaPos)));
            }
            else
            {
                token     = strLTrim(strRTrim(remaining));
                remaining = '';
            }
            if (token)
            {
                parsedIds.addEnd(token);
            }
        }

        totalTasks = parsedIds.elements();
        if (totalTasks == 0)
        {
            throw error("No valid order IDs found in the list.");
        }

        batchHeader.parmCaption(strFmt("Bulk Order Processing - %1 orders", totalTasks));

        taskNum = 0;
        le      = parsedIds.getEnumerator();
        while (le.moveNext())
        {
            taskNum++;
            worker              = new METTESTBulkSalesOrderGenerationJob();
            worker.isCopyMode   = isCopyMode;
            worker.orderCount   = totalTasks;
            worker.runPart1     = runPart1;
            worker.runPart2     = runPart2;
            worker.runPart3     = runPart3;
            worker.runPart4     = runPart4;
            worker.runPart5a    = runPart5a;
            worker.runPart5b    = runPart5b;
            worker.runPart5c    = runPart5c;
            worker.orderIndex   = taskNum;
            worker.taskOrderId  = le.current();
            batchHeader.addTask(worker);
        }

        info(strFmt("Batch job submitted: %1 order(s) queued for processing.", totalTasks));
    }

    batchHeader.save();
}

// =========================================================================
// WORKER — full order processing for one task
//
// taskOrderId meaning depends on mode + Part 1:
//   runPart1 = true  (copy mode)  → source order to copy FROM; a new order is created
//   runPart1 = false (list mode)  → existing order to process; Parts 2-5 act on it directly
// =========================================================================

private void processSingleOrder()
{
    // --- Configuration ---
    str batchId         = "Default";
    str wmsLocation     = "3WMS";

    // --- Sales Order variables ---
    SalesTable                          salesTable, salesTableCopyFrom, salesTableCheck;
    SalesLine                           salesLine, salesLineCheck, salesLineCopyFrom;
    NumberSeq                           numberSeq;

    // --- Customer / Inventory ---
    CustTable                           custTable;
    InventTable                         inventTable;
    InventDim                           inventDimUpdate;
    InventTransId                       inventTransId;

    // --- MET Custom Extension ---
    METSalesLine                        metSalesLine, metSalesLineCheck, metSalesLineCopyFrom;
    METSalesTable                       metSalesTable, metSalesTableCopyFrom;
    METSalesLinePriceComponent          metSalesLinePriceComponent, metSalesLinePriceComponentCopyFrom;
    METSalesLinePriceComponentDetail    metSalesLinePriceComponentDetail, metSalesLinePriceComponentDetailCopyFrom;
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader;
    METSalesOrderShipmentLoadLines      soShipmenLoadtLines;
    METTotes                            totes;

    // --- TMS ---
    TMSSalesTable                       tmsSalesTableCopyFrom, tmsSalesTable;

    // --- WMS ---
    WMSOrderTrans                       wmsOrderTrans, wmsOrderTransCheck;

    // --- Controllers / Contracts ---
    METSalesPickingListGenerationController             controller;
    METSalesPickingListGenerationContract               dataContract;
    METSalesPickingListGenerationTaskController         taskController;
    METSalesPickingListGenerationTaskContract           taskContract;
    METSalesOrderShipmentConfirmationController         metSalesOrderShipmentConfirmationController;
    METSalesOrderShipmentConfirmationContract           confirmationContract;
    METDallasPicklistRegContract                        dallasContract;

    // --- Business Process ---
    METTMSEngineOrderProccess           process;
    METOrderShipmentLoadCreation        shipmentLoadCreation;
    METSalesOrderGuideCheckTaskService  guideCheckService;
    METPickingListRegistrationPostingJob pickingListJob;
    SalesFormLetter                     salesFormLetter;
    MetContainerTable                   containerTable;

    // --- Utility ---
    Args                                args;
    List                                shipIdList;
    str                                 listOfShipment;
    container                           wmsOrderTransCon;

    // --- Retry ---
    int                                 maxWaitTime, waitInterval, totalWaitTime;
    boolean                             wmsDataReady, shipmentDataReady;
    ;

    // =====================================================================
    // PART 1: SALES ORDER CREATION
    // Runs in copy mode when runPart1 = true.
    // Skipped in list mode — salesTable is loaded from taskOrderId instead.
    // =====================================================================

    if (runPart1 == NoYes::Yes || runPart2 == NoYes::Yes)
    {
        ttsBegin;

        if (runPart1 == NoYes::Yes)
        {
            salesTableCopyFrom = SalesTable::find(taskOrderId);
            if (!salesTableCopyFrom.RecId)
            {
                throw error(strFmt("Task %1: Source order %2 not found.", orderIndex, taskOrderId));
            }

            custTable = CustTable::find(salesTableCopyFrom.CustAccount);
            if (!custTable.RecId)
            {
                throw error(strFmt("Task %1: Customer %2 not found.", orderIndex, salesTableCopyFrom.CustAccount));
            }

            // --- Header ---
            numberSeq                               = NumberSeq::newGetNum(SalesParameters::numRefSalesId());
            salesTable.SalesId                      = numberSeq.num();
            salesTable.CustAccount                  = custTable.AccountNum;
            salesTable.initFromCustTable();
            salesTable.SalesType                    = SalesType::Sales;
            salesTable.InventSiteId                 = salesTableCopyFrom.InventSiteId;
            salesTable.InventLocationId             = salesTableCopyFrom.InventLocationId;
            salesTable.CustomerRef                  = salesTableCopyFrom.CustomerRef;
            salesTable.ReceiptDateConfirmed         = today() + 3;
            salesTable.ReceiptDateRequested         = today() + 3;
            salesTable.ShippingDateConfirmed        = today() + 3;
            salesTable.ShippingDateRequested        = today() + 3;
            salesTable.GUPSkipPricingCalculation    = NoYes::Yes;
            salesTable.METRoute                     = METTESTBulkSalesOrderGenerationJob::generateMETRoute(custTable.AccountNum, salesTable.ShippingDateConfirmed);
            salesTable.METSalesOrderType            = salesTableCopyFrom.METSalesOrderType;
            salesTable.METRouteStopNum              = salesTableCopyFrom.METRouteStopNum;
            salesTable.modifiedField(fieldNum(salesTable, METRouteStopNum));
            salesTable.METIOMSyncComplete           = NoYes::Yes;
            salesTable.METAllowBackOrders           = salesTableCopyFrom.METAllowBackOrders;
            salesTable.METOrderExtractStatus        = METOrderExtractStatus::Open;
            salesTable.METIntercompanyTransferFulfillment = salesTableCopyFrom.METIntercompanyTransferFulfillment;

            if (!salesTable.validateWrite())
            {
                throw error(strFmt("Task %1: Sales order header validation failed.", orderIndex));
            }

            salesTable.insert();

            // --- TMS Sales Table ---
            tmsSalesTableCopyFrom = TMSSalesTable::find(salesTableCopyFrom.SalesId);
            if (tmsSalesTableCopyFrom)
            {
                tmsSalesTable.SalesId = salesTable.SalesId;
                tmsSalesTable.setCarrierFields(tmsSalesTableCopyFrom.CarrierCode,
                                               tmsSalesTableCopyFrom.CarrierServiceCode);
                if (tmsSalesTable.validateWrite())
                {
                    tmsSalesTable.write();
                }
            }

            // --- Lines ---
            while select salesLineCopyFrom
                where salesLineCopyFrom.SalesId == salesTableCopyFrom.SalesId
            {
                inventTable = InventTable::find(salesLineCopyFrom.ItemId);

                salesLine.clear();
                salesLine.SalesId                   = salesTable.SalesId;
                salesLine.ItemId                    = inventTable.ItemId;
                salesLine.SalesQty                  = salesLineCopyFrom.SalesQty;
                salesLine.QtyOrdered                = salesLineCopyFrom.QtyOrdered;
                salesLine.SalesPrice                = salesLineCopyFrom.SalesPrice;
                salesLine.SalesUnit                 = salesLineCopyFrom.SalesUnit;
                salesLine.LineAmount                = salesLine.QtyOrdered * salesLineCopyFrom.SalesPrice;
                salesLine.ShippingDateConfirmed     = salesTable.ShippingDateConfirmed;
                salesLine.ShippingDateRequested     = salesTable.ShippingDateRequested;
                salesLine.createLine(true, true, true, true, true, true, true);

                inventDimUpdate                     = salesLine.inventDim();
                inventDimUpdate.InventBatchId       = batchId;
                inventDimUpdate.wMSLocationId       = wmsLocation;
                inventDimUpdate                     = InventDim::findOrCreate(inventDimUpdate);
                salesLine.InventDimId               = inventDimUpdate.inventDimId;
                salesLine.SalesPrice                = salesLineCopyFrom.SalesPrice;
                salesLine.modifiedField(fieldNum(SalesLine, SalesPrice));
                salesLine.update();

                inventTransId = salesLine.InventTransId;

                metSalesLineCopyFrom = METSalesLine::find(salesLineCopyFrom.RecId);
                metSalesLine         = METSalesLine::find(salesLine.RecId, true);
                metSalesLine.OrderExtractStatus  = METOrderExtractStatus::Open;
                metSalesLine.OrderedQuantity     = salesLine.QtyOrdered;
                metSalesLine.SupplyingWarehouse  = metSalesLineCopyFrom.SupplyingWarehouse;
                metSalesLine.update();

                while select metSalesLinePriceComponentCopyFrom
                    where metSalesLinePriceComponentCopyFrom.InventTransId == salesLineCopyFrom.InventTransId
                {
                    metSalesLinePriceComponent.clear();
                    metSalesLinePriceComponent.InventTransId    = salesLine.InventTransId;
                    metSalesLinePriceComponent.Component        = metSalesLinePriceComponentCopyFrom.Component;
                    metSalesLinePriceComponent.PriceCodeRef     = metSalesLinePriceComponentCopyFrom.PriceCodeRef;
                    metSalesLinePriceComponent.Value            = metSalesLinePriceComponentCopyFrom.Value;
                    metSalesLinePriceComponent.FeeCode          = metSalesLinePriceComponentCopyFrom.FeeCode;
                    metSalesLinePriceComponent.insert();
                }

                while select metSalesLinePriceComponentDetailCopyFrom
                    where metSalesLinePriceComponentDetailCopyFrom.InventTransId == salesLineCopyFrom.InventTransId
                {
                    metSalesLinePriceComponentDetail.clear();
                    metSalesLinePriceComponentDetail.InventTransId  = salesLine.InventTransId;
                    metSalesLinePriceComponentDetail.Component      = metSalesLinePriceComponentDetailCopyFrom.Component;
                    metSalesLinePriceComponentDetail.Code           = metSalesLinePriceComponentDetailCopyFrom.Code;
                    metSalesLinePriceComponentDetail.Reference      = metSalesLinePriceComponentDetailCopyFrom.Reference;
                    metSalesLinePriceComponentDetail.FromDate       = metSalesLinePriceComponentDetailCopyFrom.FromDate;
                    metSalesLinePriceComponentDetail.ToDate         = metSalesLinePriceComponentDetailCopyFrom.ToDate;
                    metSalesLinePriceComponentDetail.Value          = metSalesLinePriceComponentDetailCopyFrom.Value;
                    metSalesLinePriceComponentDetail.VendorValue    = metSalesLinePriceComponentDetailCopyFrom.VendorValue;
                    metSalesLinePriceComponentDetail.PriceCodeRef   = metSalesLinePriceComponentDetailCopyFrom.PriceCodeRef;
                    metSalesLinePriceComponentDetail.insert();
                }
            }

            // --- MET Sales Table (init from copy source) ---
            metSalesTable     = METSalesTable::findBySalesTable(salesTable.RecId, true);
            metSalesTableCopyFrom = METSalesTable::findBySalesTable(salesTableCopyFrom.RecId);

            if (!metSalesTable)
            {
                throw error(strFmt("Task %1: METSalesTable not found for order %2.", orderIndex, salesTable.SalesId));
            }

            metSalesTable.OrderProcessingStatus             = METSalesOrderProcessingStatus::OptimisationCompleted;
            metSalesTable.StagingLaneId                     = metSalesTableCopyFrom.StagingLaneId;
            metSalesTable.SupplyingWarehouse                = metSalesTableCopyFrom.SupplyingWarehouse;
            metSalesTable.SupplyingSiteId                   = metSalesTableCopyFrom.SupplyingSiteId;
            metSalesTable.DoorNum                           = metSalesTableCopyFrom.DoorNum;
            metSalesTable.SupplierReference                 = metSalesTableCopyFrom.SupplierReference;
            metSalesTable.PromotionId                       = metSalesTableCopyFrom.PromotionId;
            metSalesTable.EventId                           = metSalesTableCopyFrom.EventId;
            metSalesTable.ExternalOrderNumber               = metSalesTableCopyFrom.ExternalOrderNumber;
            metSalesTable.PromoDueDate                      = metSalesTableCopyFrom.PromoDueDate;
            metSalesTable.PromoExtDays                      = metSalesTableCopyFrom.PromoExtDays;
            metSalesTable.PromoExtTerms                     = metSalesTableCopyFrom.PromoExtTerms;
            metSalesTable.PromoExtTermsMethod               = metSalesTableCopyFrom.PromoExtTermsMethod;
            metSalesTable.ExtendedTermsMethod               = metSalesTableCopyFrom.ExtendedTermsMethod;
            metSalesTable.ExtendedDate                      = metSalesTableCopyFrom.ExtendedDate;
            metSalesTable.ExtendedTerms                     = metSalesTableCopyFrom.ExtendedTerms;
            metSalesTable.SalesCutOffDay                    = metSalesTableCopyFrom.SalesCutOffDay;
            metSalesTable.SalesDispatchDay                  = metSalesTableCopyFrom.SalesDispatchDay;
            metSalesTable.SalesCutOffTime                   = metSalesTableCopyFrom.SalesCutOffTime;
            metSalesTable.SalesDispatchTime                 = metSalesTableCopyFrom.SalesDispatchTime;
            metSalesTable.SecondRoute                       = metSalesTableCopyFrom.SecondRoute;
            metSalesTable.SecondShipDate                    = metSalesTableCopyFrom.SecondShipDate;
            metSalesTable.SecondRouteStopNum                = metSalesTableCopyFrom.SecondRouteStopNum;
            metSalesTable.SecondaryStagingLaneId            = metSalesTableCopyFrom.SecondaryStagingLaneId;
            metSalesTable.SecondaryDoorNum                  = metSalesTableCopyFrom.SecondaryDoorNum;
            metSalesTable.OriginalRouteIdentifier           = metSalesTableCopyFrom.OriginalRouteIdentifier;
            metSalesTable.OriginalSecondRouteIdentifier     = metSalesTableCopyFrom.OriginalSecondRouteIdentifier;
            metSalesTable.OriginalRouteStopIdentifier       = metSalesTableCopyFrom.OriginalRouteStopIdentifier;
            metSalesTable.OriginalSecondRouteStopIdentifier = metSalesTableCopyFrom.OriginalSecondRouteStopIdentifier;
            metSalesTable.SecondaryCarrierCode              = metSalesTableCopyFrom.SecondaryCarrierCode;
            metSalesTable.SecondaryCarrierServiceCode       = metSalesTableCopyFrom.SecondaryCarrierServiceCode;
            metSalesTable.PDEserialNumber                   = metSalesTableCopyFrom.PDEserialNumber;
            metSalesTable.DeliveryInstructions              = metSalesTableCopyFrom.DeliveryInstructions;
            metSalesTable.OrderReleaseDate                  = metSalesTableCopyFrom.OrderReleaseDate;
            metSalesTable.InternalCrossDockOrder            = metSalesTableCopyFrom.InternalCrossDockOrder;
            metSalesTable.IndustryKey                       = metSalesTableCopyFrom.IndustryKey;
            metSalesTable.ExcludeFromDualWrite              = metSalesTableCopyFrom.ExcludeFromDualWrite;
            metSalesTable.CustomCreditCheckExecute          = metSalesTableCopyFrom.CustomCreditCheckExecute;
            metSalesTable.OrderSplitGroup                   = metSalesTableCopyFrom.OrderSplitGroup;
            metSalesTable.LinkedSalesAgreement              = metSalesTableCopyFrom.LinkedSalesAgreement;
            metSalesTable.IsManual                          = metSalesTableCopyFrom.IsManual;
            metSalesTable.WMSOrderType                      = metSalesTableCopyFrom.WMSOrderType;
            metSalesTable.TransmissionDateTime              = DateTimeUtil::utcNow();
            metSalesTable.ReleaseDate                       = today();
            metSalesTable.update();

            info(strFmt("Task %1/%2: Sales order %3 created.", orderIndex, orderCount, salesTable.SalesId));
        }
        else  // runPart1 == NoYes::No — list mode, load existing order
        {
            salesTable = SalesTable::find(taskOrderId);
            if (!salesTable.RecId)
            {
                throw error(strFmt("Task %1: Order %2 not found.", orderIndex, taskOrderId));
            }
        }

        // =================================================================
        // PART 2: CONFIRMATION (TMS engine + SalesFormLetter)
        // =================================================================

        if (runPart2 == NoYes::Yes)
        {
            // TMS Engine
            process = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderCreation, salesTable);
            process.run();

            // Sales Confirmation
            salesTable.reread();
            salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);
            salesFormLetter.update(salesTable,
                                  DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                  SalesUpdate::All);
        }

        ttsCommit;
    }

    // If neither Part 1 nor Part 2 ran, ensure salesTable is populated for Parts 3-5
    if (runPart1 == NoYes::No && runPart2 == NoYes::No
        && (runPart3 == NoYes::Yes || runPart4 == NoYes::Yes || runPart5a == NoYes::Yes || runPart5b == NoYes::Yes || runPart5c == NoYes::Yes))
    {
        salesTable = SalesTable::find(taskOrderId);
        if (!salesTable.RecId)
        {
            throw error(strFmt("Task %1: Order %2 not found.", orderIndex, taskOrderId));
        }
    }

    // =====================================================================
    // PART 3: EXTRACTION
    // =====================================================================

    if (runPart3 == NoYes::Yes)
    {
        ttsBegin;

        // Picking List
        args = new Args();
        args.record(salesTable);
        controller   = METSalesPickingListGenerationController::construct(args);
        dataContract = controller.getDataContractObject();
        dataContract.parmSalesOrderList(str2con(salesTable.SalesId));
        controller.parmShowDialog(false);
        controller.startOperation();

        // Guide Check for Backorders
        while select salesLineCheck
                where salesLineCheck.SalesId == salesTable.SalesId &&
                      salesLineCheck.SalesStatus == SalesStatus::Backorder
                join ReasonId from metSalesLineCheck
                    where metSalesLineCheck.SalesLine == salesLineCheck.RecId &&
                          (metSalesLineCheck.ReasonId == METConstants::NIRReasonCode ||
                           metSalesLineCheck.ReasonId == METConstants::NewReasonCode)
                exists join salesTableCheck
                    where salesTableCheck.SalesId == salesLineCheck.SalesId &&
                          salesTableCheck.METOrderExtractStatus == METOrderExtractStatus::Open
        {
            guideCheckService = new METSalesOrderGuideCheckTaskService();
            guideCheckService.performSOGuideCheck(salesLineCheck);
        }

        // Shipment Load
        taskController = METSalesPickingListGenerationTaskController::construct();
        taskContract   = taskController.getDataContractObject();
        taskContract.parmSalesId(salesTable.SalesId);

        shipmentLoadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::SalesOrder,
                                                                           taskContract.parmSalesId());
        shipmentLoadCreation.createShippmentLoad(true, true);

        salesTable.reread();
        salesTable.METOrderExtractDateTime = DateTimeUtil::getSystemDateTime();
        salesTable.update();

        taskContract.parmTriggerBusinessEvent(true);
        taskContract.parmShipmentIdList(str2con(salesTable.SalesId));
        taskController.parmShowDialog(false);
        taskController.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        taskController.runOperation();

        ttsCommit;

        // Wait for WMSOrderTrans records
        maxWaitTime     = 60;
        totalWaitTime   = 0;
        wmsDataReady    = false;

        while (totalWaitTime < maxWaitTime && !wmsDataReady)
        {
            waitInterval = (totalWaitTime == 0) ? 30 : 10;

            if (totalWaitTime + waitInterval <= maxWaitTime)
            {
                METGlobal::sleep(waitInterval);
                totalWaitTime += waitInterval;
            }
            else
            {
                waitInterval = maxWaitTime - totalWaitTime;
                if (waitInterval > 0)
                {
                    METGlobal::sleep(waitInterval);
                    totalWaitTime += waitInterval;
                }
            }

            select firstonly RecId from wmsOrderTransCheck
                exists join salesLine
                    where salesLine.SalesId              == salesTable.SalesId &&
                          wmsOrderTransCheck.inventTransId == salesLine.InventTransId;

            if (wmsOrderTransCheck.RecId)
            {
                wmsDataReady = true;
                info(strFmt("Task %1: WMSOrderTrans ready after %2 seconds.", orderIndex, totalWaitTime));
            }
            else if (totalWaitTime >= maxWaitTime)
            {
                throw error(strFmt("Task %1: Timeout — WMSOrderTrans not available after %2 seconds.",
                                  orderIndex, totalWaitTime));
            }
        }
    }

    // =====================================================================
    // PART 4: DALLAS PICKING LIST COMPLETION
    // =====================================================================

    if (runPart4 == NoYes::Yes)
    {
        ttsBegin;

        while select salesLine
                where salesLine.SalesId == salesTable.SalesId
        {
            select forUpdate wmsOrderTrans
                    where wmsOrderTrans.inventTransId == salesLine.InventTransId;

            if (wmsOrderTrans)
            {
                wmsOrderTrans.METPickedQtyUpdated = NoYes::Yes;
                wmsOrderTrans.update();

                wmsOrderTransCon = [wmsOrderTrans.RecId];
                dallasContract   = new METDallasPicklistRegContract();
                dallasContract.parmConOrderTrans(wmsOrderTransCon);

                pickingListJob = new METPickingListRegistrationPostingJob();
                pickingListJob.postPickListRegistration(dallasContract);
            }
        }

        ttsCommit;

        // Wait for METSalesOrderShipmentLoadHeader
        maxWaitTime       = 60;
        totalWaitTime     = 0;
        shipmentDataReady = false;

        while (totalWaitTime < maxWaitTime && !shipmentDataReady)
        {
            waitInterval = (totalWaitTime == 0) ? 30 : 10;

            if (totalWaitTime + waitInterval <= maxWaitTime)
            {
                METGlobal::sleep(waitInterval);
                totalWaitTime += waitInterval;
            }
            else
            {
                waitInterval = maxWaitTime - totalWaitTime;
                if (waitInterval > 0)
                {
                    METGlobal::sleep(waitInterval);
                    totalWaitTime += waitInterval;
                }
            }

            shipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOpenLoad(salesTable.METRoute,
                                                                               salesTable.ShippingDateConfirmed,
                                                                               salesTable.InventLocationId,
                                                                               METOrderTransactionType::SalesOrder);

            if (shipmentLoadHeader.RecId)
            {
                shipmentDataReady = true;
                info(strFmt("Task %1: ShipmentLoadHeader found after %2 seconds.", orderIndex, totalWaitTime));
            }
            else if (totalWaitTime >= maxWaitTime)
            {
                throw error(strFmt("Task %1: Timeout — ShipmentLoadHeader not available after %2 seconds.",
                                  orderIndex, totalWaitTime));
            }
        }
    }

    // =====================================================================
    // PART 5a: TOTES
    // =====================================================================

    if (runPart5a == NoYes::Yes)
    {
        ttsBegin;

        totes.SalesId = salesTable.SalesId;
        totes.Tote    = '12345';
        totes.insert();

        update_recordset soShipmenLoadtLines
                setting CCRReceived = NoYes::Yes
                where soShipmenLoadtLines.OrderNum == totes.SalesId;

        info(strFmt("Task %1/%2: Totes created for order %3.", orderIndex, orderCount, salesTable.SalesId));

        ttsCommit;
    }

    // =====================================================================
    // PART 5b: CONTAINER
    // =====================================================================

    if (runPart5b == NoYes::Yes)
    {
        // shipmentLoadHeader populated by Part 4 wait loop; fetch it if Part 4 was skipped.
        if (!shipmentLoadHeader.RecId)
        {
            shipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOpenLoad(salesTable.METRoute,
                                                                               salesTable.ShippingDateConfirmed,
                                                                               salesTable.InventLocationId,
                                                                               METOrderTransactionType::SalesOrder);
        }

        ttsBegin;

        shipmentLoadHeader.selectForUpdate(true);

        if (shipmentLoadHeader)
        {
            containerTable.ContainerTypeCode = 'PAL';
            containerTable.ContainerQty      = 1;
            containerTable.TransactionType   = METOrderTransactionType::SalesOrder;
            containerTable.ShipmentId        = shipmentLoadHeader.ShipmentId;
            containerTable.insert();

            info(strFmt("Task %1/%2: Container created for shipment %3.", orderIndex, orderCount, shipmentLoadHeader.ShipmentId));
        }

        ttsCommit;
    }

    // =====================================================================
    // PART 5c: SHIPMENT CONFIRMATION
    // =====================================================================

    if (runPart5c == NoYes::Yes)
    {
        // Ensure shipmentLoadHeader is populated if Parts 4 and 5b were both skipped.
        if (!shipmentLoadHeader.RecId)
        {
            shipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOpenLoad(salesTable.METRoute,
                                                                               salesTable.ShippingDateConfirmed,
                                                                               salesTable.InventLocationId,
                                                                               METOrderTransactionType::SalesOrder);
        }

        ttsBegin;

        shipIdList = new List(Types::String);
        args       = new Args();
        args.record(shipmentLoadHeader);

        shipmentLoadHeader.checkAndUpdateCCR();

        if (shipmentLoadHeader.RecId &&
                shipmentLoadHeader.ShipmentStatus != MetShipmentStatus::Shipped &&
                shipmentLoadHeader.isValidShipmentToShipped() &&
                shipmentLoadHeader.isSOLineRelatedTORecevied())
        {
            shipIdList.addEnd(shipmentLoadHeader.ShipmentId);
            listOfShipment += ' | ' + shipmentLoadHeader.ShipmentId;

            shipmentLoadHeader.ShipmentStatus = MetShipmentStatus::Loaded;
            shipmentLoadHeader.update();

            info(strFmt("@MET:ShipmentUpdateMsg", shipmentLoadHeader.ShipmentId, shipmentLoadHeader.ShipmentStatus));

            METSalesOrderShipmentLoadHeader::updateLoadStatus(shipmentLoadHeader.LoadId);
        }
        else
        {
            error(strFmt("@MET:InvalidShipment", shipmentLoadHeader.ShipmentId));
        }

        if (!shipIdList.empty())
        {
            metSalesOrderShipmentConfirmationController = METSalesOrderShipmentConfirmationController::construct(args);
            metSalesOrderShipmentConfirmationController.parmExecutionMode(SysOperationExecutionMode::Synchronous);
            metSalesOrderShipmentConfirmationController.parmShowDialog(false);

            confirmationContract = metSalesOrderShipmentConfirmationController.getDataContractObject('_contract')
                                      as METSalesOrderShipmentConfirmationContract;
            confirmationContract.parmShipmentIdList(shipIdList);
            confirmationContract.parmThreadCount(1);
            metSalesOrderShipmentConfirmationController.parmDialogCaption(strFmt("@MET:ShipmentConfirm", listOfShipment));
            metSalesOrderShipmentConfirmationController.batchInfo().parmBatchExecute(true);
            metSalesOrderShipmentConfirmationController.startOperation();
        }

        info(strFmt("Task %1/%2: Order %3 shipment confirmed.", orderIndex, orderCount, salesTable.SalesId));

        ttsCommit;
    }
}

// =========================================================================
// HELPER METHODS
// =========================================================================

/// <summary>
/// Generates a unique METRoute code (CustomerPrefix + 2-digit sequence) that
/// does not collide with any existing order for the same customer and shipping date.
/// </summary>
private static str generateMETRoute(CustAccount _custAccount, TransDate _shippingDate)
{
    SalesTable  salesTableCount;
    SalesTable  salesTableCheck;
    int         seq;
    str         routeCode;
    str         prefix;
    ;

    select count(RecId) from salesTableCount
        where salesTableCount.CustAccount          == _custAccount &&
              salesTableCount.ShippingDateConfirmed == _shippingDate;

    seq    = any2Int(salesTableCount.RecId) + 1;
    prefix = substr(_custAccount, 1, 2);

    routeCode = (seq <= 99) ? prefix + strLFix(int2str(seq), 2, '0')
                            : strLFix(int2str(seq), 4, '0');

    while (true)
    {
        select firstonly RecId from salesTableCheck
            where salesTableCheck.METRoute             == routeCode &&
                  salesTableCheck.ShippingDateConfirmed == _shippingDate;

        if (!salesTableCheck.RecId)
        {
            break;
        }

        seq++;
        routeCode = (seq <= 99) ? prefix + strLFix(int2str(seq), 2, '0')
                                : strLFix(int2str(seq), 4, '0');
    }

    return routeCode;
}

// =========================================================================
// ENTRY POINT
// =========================================================================

static void main(Args _args)
{
    METTESTBulkSalesOrderGenerationJob job = METTESTBulkSalesOrderGenerationJob::construct();
    ;
    if (job.prompt())
    {
        job.runOperation();
    }
}

static METTESTBulkSalesOrderGenerationJob construct()
{
    return new METTESTBulkSalesOrderGenerationJob();
}
